-- Catálogo, parte 4 de 4. Correr en orden, después de 01_esquema.sql.
insert into public.peliculas (tmdb_id, media_type, titulo, titulo_tmdb, titulo_original, anio, direccion, sinopsis, poster_path, backdrop_path, vote_average, trailer_youtube, listas, pagina_libro, donde_ver, cruce, candidatos) values
(922, 'movie', 'Dead Man', 'Dead Man', 'Dead Man', 1995, 'Jim Jarmusch', 'William Blake decide abandonar su puesto de contable en Cleveland (Ohio) después de recibir una oferta de trabajo en Machine, una inhóspita ciudad industrial en el Oeste de los EEUU. Sin embargo, cuando llega, resulta que su puesto lo ocupa otra persona. Charlie Dickinson, el hijo del propietario de la empresa, mata a su mujer cuando la encuentra en la cama con Blake, quien a su vez liquida a Charlie. De este modo, un simple contable de Cleveland se convierte en un "fugitivo" perseguido por tres cazadores de recompensas.', '/in1wyJhudwwfLS6Ad2Q6wYJGUAv.jpg', '/a7DtgKB187dUm9n81IlvNzVXsK1.jpg', 7.3, 'FEHMWguT--U', array['1001']::text[], 859, null, 'segura', null),
(275, 'movie', 'Fargo', 'Fargo', 'Fargo', 1996, 'Joel Coen', 'Un hombre apocado y tímido, casado con la hija de un millonario que le impide disfrutar de su fortuna, decide contratar a dos delincuentes para que secuestren a su mujer con el fin de montar un negocio propio con el dinero del rescate. Pero, por una serie de azarosas circunstancias, al secuestro se suman tres brutales asesinatos, lo que obliga a la policía a intervenir.', '/e25EHAVCA16rnbeAYl8qrSrc942.jpg', '/747dgDfL5d8esobk7h4odaOFhUq.jpg', 7.8, 'Pg_CqV3VlPg', array['1001']::text[], 860, null, 'segura', null),
(7863, 'movie', 'Shine', 'Shine. El resplandor de un genio', 'Shine', 1996, 'Scott Hicks', 'Basada en hechos reales, narra la historia de David Helfgott, un brillante y virtuoso pianista australiano cuya insoportable presión paterna le traumatizó hasta el punto de alcanzar estados de demencia y sufrir internamiento en un asilo.', '/6uosW3xgGk2BnQVq84D3ix5FH2j.jpg', '/2NU8w8djgX6SzLrg7rN6yMXWAzC.jpg', 7.4, 'NaF9JIhPgdU', array['1001']::text[], 862, null, 'segura', null),
(55049, 'movie', 'Tres vidas y una sola muerte', 'Tres vidas y una sola muerte', 'Trois vies et une seule mort', 1996, 'Raúl Ruiz', 'En París suceden tres historias que, en principio, parece que no tienen nada que ver entre sí. Un viajante sale a comprar cerillas y regresa veinte años más tarde. Un catedrático de Universidad se hace pasar por mendigo. Finalmente, un hombre de negocios se inventa una familia ficticia en el extranjero para ocultar oscuros asuntos financieros.', '/dRYD6rZIQuICh7KtfMXL3Nbz9j8.jpg', '/49PxbsbF5QoAlqQPUNsu8IMqbUN.jpg', 6.5, null, array['1001']::text[], 862, null, 'segura', null),
(145, 'movie', 'Rompiendo las olas', 'Rompiendo las olas', 'Breaking the Waves', 1996, 'Lars von Trier', 'A principios de los años 70, Bess (Watson), una ingenua joven de un pueblo costero de Escocia, se enamora de Jan (Stellan Skarsgård), un hombre mundano que trabaja en una plataforma petrolífera. A pesar de la oposición de la rígida comunidad puritana a la que pertenece, Bess y Jan se casan. Tras la boda, él vuelve a su trabajo, y ella cuenta los días esperando su vuelta. Bess, una creyente devota, cree que su amor está bendecido por el cielo; pero un día sucede un terrible accidente. Primera película de la trilogía "Corazón dorado" de Lars Von Trier.', '/hb7ksXgZrWuO4u4AIaJKz5aIh2e.jpg', '/nY2faCdUVHzuH6FmDI6QsAURE68.jpg', 7.5, 'dPmWixRLFPQ', array['1001']::text[], 863, null, 'segura', null),
(602, 'movie', 'Independence Day', 'Independence Day', 'Independence Day', 1996, 'Roland Emmerich', 'En víspera del 4 de julio, unas gigantescas naves espaciales aparecen en el cielo. El estupor inicial se convierte en terror al ver cómo éstas atacan al planeta lanzando rayos destructivos en las mayores ciudades de todo el mundo. Ahora la única esperanza para la salvación de la tierra está en la voluntad de algunos supervivientes, que se unen planeando el último ataque masivo contra los alienígenas, antes de que sea demasiado tarde para la humanidad.', '/zhYisFUKLhlrbcrABMxQRzwuAM5.jpg', '/kFI1oF6KVnLEbUT7yLIbKXeyvu.jpg', 6.9, 'E19dTE5ejmA', array['1001']::text[], 864, null, 'segura', null),
(43771, 'movie', 'Gabbeh', 'Gabbeh', 'گبه', 1996, 'محسن مخملباف', 'Una pareja de ancianos vive apartada de los hombres y cuida del gabbeh, la alfombra que narra la vida del clan al que ella pertenece. Poco a poco aflora el pasado de los amantes fugitivos que han infringido la ley ancestral. El cuento o el arte de tejer remotos y arquetípicos motivos amorosos.', '/oa1ap3SlARqFUMJs0467g9f4OUS.jpg', '/uv0annzJaX9iGrzQOTTmHD63qPJ.jpg', 6.7, 'mFFkf0hNgVw', array['1001']::text[], 865, null, 'segura', null),
(11159, 'movie', 'Secretos y mentiras', 'Secretos y mentiras', 'Secrets & Lies', 1996, 'Mike Leigh', 'Al morir sus padres adoptivos, Hortense, una joven negra que vive en Londres, siente la necesidad de conocer a su madre biológica, la cual la dio en adopción nada más nacer. Cuando por fin la encuentra, resulta ser una mujer soltera que trabaja en una fábrica.', '/zETSgsWXpOIsJjpCl8UoxcJqPlX.jpg', '/oLh3r9BhrymkMjKtI2geTGkKMif.jpg', 7.6, 'dSnI4_6DrFw', array['1001']::text[], 865, null, 'segura', null),
(26748, 'movie', 'Lone Star', 'Lone Star', 'Lone Star', 1996, 'John Sayles', 'En el desierto de Texas, en un pueblo con numerosos inmigrantes mexicanos, aparece un hombre muerto. Durante la investigación, el sheriff encargado del caso tendrá que enfrentarse con algunos enigmas de su pasado.', '/lBxY8znsRoqa9Dy2NCe8I6GPsRm.jpg', '/vsxo1dkhRHd9YT9Um5IaxvnF8Yt.jpg', 7.0, 'plMNsde4_-M', array['1001']::text[], 866, null, 'segura', null),
(627, 'movie', 'Trainspotting', 'Trainspotting', 'Trainspotting', 1996, 'Danny Boyle', 'Mark Renton es un joven escocés adicto a la heroína, al igual que el resto de sus amigos Todos ellos viven en un mundo aparte, al margen de la realidad. Dentro del grupo hay un violento y alcohólico psicópata, un drogadicto desesperado, un mujeriego con un conocimiento enciclopédico de Sean Connery y un entusiasta de las caminatas y de Iggy Pop.', '/qSG5r7pympUa2urtblJrpKQGb2q.jpg', '/dkfBKDUIWP1peEszdqK10MkMZCP.jpg', 8.0, 'bKrbNruyFVE', array['1001']::text[], 867, null, 'segura', null),
(4232, 'movie', 'Scream, vigila quién llama', 'Scream. Vigila quién llama', 'Scream', 1996, 'Wes Craven', 'Sidney Prescott, una adolescente de la pequeña comunidad de Woodsboro, se convierte en el objetivo de un misterioso asesino en serie. Una reportera de un canal de noticias, Gale Weathers, que cubrió el asesinato un año atrás de la madre de Sidney, cubre ahora estos asesinatos, además ha escrito un libro en el que defiende al supuesto asesino de Maureen, Cotton Weary, que va a ir a la cámara de gas, alegando que cayó en una trampa, lo que hace reavivar la polémica. Los crímenes dejan de ser aislados y continúan los asesinatos. Ahora Sidney, su novio y sus amigos están en peligro, ya que el asesino quiere revivir lo sucedido un año atrás con Maureen Prescott, pero esta vez con su hija.', '/pO39MWOrEmJYthKyWT79BYCVRrO.jpg', '/4w6nQYAY0eb7B0VVRDXilXcgAUV.jpg', 7.4, '0-zoiOxFA_M', array['1001']::text[], 868, null, 'segura', null),
(409, 'movie', 'El paciente inglés', 'El paciente inglés', 'The English Patient', 1996, 'Anthony Minghella', 'Finales de la Segunda Guerra Mundial. Un hombre herido viaja en una caravana por una carretera de Italia, pero su estado es tan grave que se tiene que quedar en un monasterio deshabitado y semiderruido, donde se encarga de cuidarlo Hana, una enfermera canadiense. Su cuerpo está totalmente quemado a consecuencia de un accidente sufrido en África, pero todavía tiene tiempo para contarle la trágica historia de su vida.', '/rFrE4iRB9Cdj2T3H1JeeV6DOuL8.jpg', '/em5kAUF8QbwThG5BCqVgFomxNT5.jpg', 7.1, 'Xk_LRcOFT0c', array['1001']::text[], 870, null, 'segura', null),
(18329, 'movie', 'Happy Together', 'Happy Together', '春光乍洩', 1997, 'Wong Kar-wai', 'Lai Yiu-Kai y Ho Po-Wing viven una apasionada relación. Viajan desde Hong Kong a Argentina, pero la llegada al nuevo país parece transformar las cosas y Ho, de repente, abandona a Lai. Éste comienza a trabajar como portero de un bar, con el único afán de reunir el dinero suficiente para volver a su país. Un día Ho reaparece, pero las cosas ya no son iguales...', '/9OYXLgM5C9wZbbVgIMDlQu2rC9N.jpg', '/2Xkd3WeAx11cHxb4Lr3wnSNDWcd.jpg', 7.6, 'cU_u8xQspQg', array['1001']::text[], 871, null, 'segura', null),
(128, 'movie', 'La princesa Mononoke', 'La princesa Mononoke', 'もののけ姫', 1997, 'Hayao Miyazaki', 'Tras sufrir el ataque de un monstruoso jabalí maldito, el joven Ashitaka emprende el camino en busca de la cura que detenga la infección. Mientras, los humanos están acabando con los bosques y los dioses convertidos en temibles bestias hacen todo lo posible por protegerlo encabezados por Mononoke, una princesa guerrera. Ashikata deberá escoger bando y decidir si ayudar a los hombres o las deidades intentando detener la maldición de su herida que se extiende por su cuerpo sin cuartel.', '/xP466sdt19CPLVljpRwI7luEgFn.jpg', '/gl0jzn4BupSbL2qMVeqrjKkF9Js.jpg', 8.3, 'I1dHzoRl0sQ', array['1001']::text[], 872, null, 'segura', null),
(22797, 'movie', 'Contracorriente', 'The Butcher Boy (Contracorriente)', 'The Butcher Boy', 1998, 'Neil Jordan', 'Francie Brady (Eamonn Owens) es un adolescente que vive en un ambiente familiar que frustra todos sus deseos y sus sueños. En pie de guerra contra la realidad que lo rodea, y dominado por un padre alcohólico (Stephen Rea) y una madre depresiva, Francie busca desesperadamente un refugio para olvidarse de su vida.', '/9KrClE5Ax6wzCAwgaGRhQI2Eolk.jpg', '/bjuH03KlisJ78ssHUzXhruoVulp.jpg', 6.8, 'mdvtR8Hup4E', array['1001']::text[], 873, null, 'segura', null),
(2118, 'movie', 'L.A. Confidential', 'L.A. Confidential', 'L.A. Confidential', 1997, 'Curtis Hanson', 'Los Ángeles, años 50. El departamento de policía vive tiempos agitados en una ciudad revuelta y sacudida continuamente por escándalos que destapa la prensa sensacionalista, y donde todo el mundo busca la fama, drogas, alcohol, sexo o dinero. Dos agentes de caracteres opuestos, en cambio, guian sus acciones por nobles sentimientos: Bud White (Russell Crowe) se mete en todo tipo de líos pero no soporta que maltraten a una mujer. Mientras, Ed Exley (Guy Pearce) es un novato que quiere "limpiar" el cuerpo de policía de la corrupción imparable que invade todo el escalafón policial, aunque le cueste el desprecio de sus compañeros. Cada uno tiene sus tareas y sus problemas, hasta que una noche aparecen muertos varios agentes en un local nocturno.', '/3xQXLqCXMTizZ7ibSERqaBKvPhY.jpg', '/hUn13Hom8OWMYpR1ay0diwswwdP.jpg', 7.8, 'QeIoelqDzsA', array['1001']::text[], 873, null, 'segura', null),
(68924, 'movie', 'La tormenta de hielo', 'La tormenta de hielo', 'The Ice Storm', 1997, 'Ang Lee', 'Noviembre de 1973, New Cannan, Connecticut. La liberación sexual tan de moda ha llegado a los suburbios y ha salpicado a las acomodadas y tradicionales familias americanas, que, de pronto, se aficionan al intercambio de parejas. Esta situación afecta a la familia Hood. Ben Hood pretende acostarse con la vecina de enfrente, pero su esposa empieza a estar harta de las mentiras de su marido. En la noche de Acción de Gracias, una serie de acontecimientos lleva a los Hood a replantearse su vida.', '/zkPnm8mCrCsMavdJYQEX39zk9bz.jpg', '/yu57dADKL9PfxHZqVfpcNEccWNv.jpg', 6.9, 'GALtpiBSG3I', array['1001']::text[], 874, null, 'segura', null),
(4995, 'movie', 'Boogie Nights', 'Boogie nights', 'Boogie Nights', 1997, 'Paul Thomas Anderson', 'A los 17 años, un joven sexualmente bien dotado (Mark Wahlberg) es descubierto por un director veterano (Burt Reynolds), que lo transforma en una celebridad de la subcultura del mundo del porno en pleno apogeo de los 70. Sin embargo, la fama repentina puede pasar factura', '/njDsPPXygxLluTcWrRKtePKIWk.jpg', '/ArpTzQZHWh4UVsgUvV6S7WjTq1n.jpg', 7.6, 'IKlXrPdyhsM', array['1001']::text[], 875, null, 'segura', null),
(2639, 'movie', 'Desmontando a Harry', 'Desmontando a Harry', 'Deconstructing Harry', 1997, 'Woody Allen', 'Harry Block, un escritor de mediana edad y con un cierto éxito, se ha servido con frecuencia de sus experiencias sentimentales y familiares para escribir sus obras, razón por la cual la mayor parte de sus amigos, parientes y ex-mujeres lo odian. En tales circunstancias, le resulta muy difícil encontrar a alguien que quiera acompañarlo en un viaje a su vieja universidad para recibir un homenaje.', '/igUstFpkI9lgHVh3VLkwKgL7WVm.jpg', '/f8Q3Sug5Sa42psw2b3Gdd1aT8t.jpg', 7.2, 'WwXOol3hRUg', array['1001']::text[], 876, null, 'segura', null),
(10217, 'movie', 'Dulce porvenir', 'El dulce porvenir', 'The Sweet Hereafter', 1997, 'Atom Egoyan', 'Adaptación de "El flautista de Hamelin". Un autobús escolar se despeña montaña abajo y se hunde en un lago helado. En el accidente mueren todos los niños del pueblo. El abogado Mitchell Stevens se entrevista con los padres, reabre sus heridas del pasado y les propone llevar el caso a los tribunales.', '/gJy7LMq4b5qO5fsSUSoBgm24BHf.jpg', '/7zRAZFZ4xVMyoLEvCb4Au41uvny.jpg', 6.9, 'zPyJ3MAlvLM', array['1001']::text[], 876, null, 'segura', null),
(10234, 'movie', 'Funny Games', 'Funny Games', 'Funny Games', 1997, 'Michael Haneke', 'Anna, Georg y su hijo Georgie van a pasar las vacaciones a su bonita casa a orillas de un lago. Sus vecinos Fred y Eva han llegado antes que ellos. Las dos parejas quedan para jugar al golf al día siguiente. Mientras padre e hijo preparan el velero, Anna prepara la cena. De repente, Peter, un joven muy educado que se aloja en casa de los vecinos, se presenta para pedir que le presten algunos huevos porque a Eva no le queda ninguno. De repente, Anna se pregunta cómo ha podido entrar en la casa. El joven le explica que Fred le ha enseñado un agujero que hay en la cerca.', '/xdqXXacYzPwVAS4AvZz87u23wyW.jpg', '/79SBe1bU30Dy6QPwJ2KQ3LTr1lr.jpg', 7.3, 'hgczUZXVKWA', array['1001']::text[], 877, null, 'segura', null),
(30020, 'movie', 'El sabor de las cerezas', 'El sabor de las cerezas', 'طعم گيلاس', 1997, 'Abbas Kiarostami', 'Un hombre de mediana edad decide suicidarse. Su única preocupación es encontrar a alguien que le ayude y se comprometa a enterrarlo. Esta situación le permite conocer a una gran variedad de personajes.', '/xjj9f4WEdE2NLO8Luf9ofNhvqCQ.jpg', '/44SNTCSZTdbF5bzgUy4IfPV3DUq.jpg', 7.7, 'ukmYdGwVqPg', array['1001']::text[], 878, null, 'segura', null),
(1902, 'movie', 'Abre los ojos', 'Abre los ojos', 'Abre los ojos', 1997, 'Alejandro Amenábar', 'César es un atractivo y apuesto joven que ha heredado una gran fortuna de sus padres. Vive en una espléndida casa de su propiedad en la que organiza lujosas fiestas. Cuando una noche su amigo Pelayo le presenta a la hermosa Sofía, Nuria, que fue amante de César, se muere de celos y, al día siguiente, yendo en coche con César, intenta suicidarse. Cuando éste se despierta en el hospital, su rostro se encuentra horriblemente desfigurado.', '/wzfbGuRYlE0bB0WdzrCnxFSWwWo.jpg', '/k6xQZq2jkA7xRpvyy2kLWprFwIN.jpg', 7.5, '1zX8gwWvke8', array['1001']::text[], 879, null, 'segura', null),
(44361, 'movie', 'Madre e hijo (Mat i syn)', 'Мать и сын', 'Мать и сын', 1997, 'Aleksandr Sokúrov', 'A man goes for a walk through the countryside with his dying mother.', '/2GhtAOmBRfykrO1D0MAEZKU5Gqg.jpg', '/rgqAb8TR2ZdzowHnsY1sBn8T6Or.jpg', 6.7, null, array['1001']::text[], 879, null, 'probable', '[{"tmdb_id": 44361, "titulo": "Mother and Son", "original": "Мать и сын", "anio": 1997, "votos": 94, "poster_path": "/Ndzs0Ry85Yn7a6D9TMImJauSGT.jpg", "sim": 0.435}]'::jsonb),
(597, 'movie', 'Titanic', 'Titanic', 'Titanic', 1997, 'James Cameron', 'Jack, un joven artista, gana en una partida de cartas un pasaje para viajar a América en el Titanic, el transatlántico más grande y seguro jamás construido. A bordo conoce a Rose, una joven de una buena familia venida a menos que va a contraer un matrimonio de conveniencia con Cal, un millonario engreído a quien sólo interesa el prestigioso apellido de su prometida. Jack y Rose se enamoran, pero el prometido y la madre de ella ponen todo tipo de trabas a su relación. Mientras, el gigantesco y lujoso transatlántico se aproxima hacia un inmenso iceberg.', '/2tltWMvvTqscFtdujTXDsRFTqKQ.jpg', '/sCzcYW9h55WcesOqA12cgEr9Exw.jpg', 7.9, '6FKmt1RcLug', array['1001']::text[], 880, null, 'segura', null),
(309, 'movie', 'Celebración', 'Celebración', 'Festen', 1998, 'Thomas Vinterberg', 'Los Klingenfeldt, una familia de la alta burguesía danesa, se disponen a celebrar el sesenta cumpleaños del patriarca, un hombre de trayectoria y reputación intachable. Sin embargo, sus tres hijos, aunque muy diferentes entre sí, están dispuestos a aprovechar la ocasión para sacar a relucir los trapos sucios de la familia.', '/ibWzFsS6Z7cTEKJIE738URYS4Mo.jpg', '/yCtgdv7TfgZLHj6R9IQKD5TjljP.jpg', 7.7, 'XCqc_JTiNxg', array['1001']::text[], 881, null, 'segura', null),
(115, 'movie', 'El gran Lebowski', 'El gran Lebowski', 'The Big Lebowski', 1998, 'Joel Coen, Ethan Coen', 'El Nota es un hombre fracasado y en paro que un día es confundido con otra persona con su mismo nombre. Dos matones irrumpen en su apartamento y destrozan su alfombra creyendo que están ante Jeff Lebowski un millonario de Pasadena. El primer error de El Nota es visitar a su opulento tocayo con la esperanza de que le reponga su vieja alfombra.Sin embargo, nuestro reticente héroe y su compinche Water se ven atrapados en un thriller con toques humorísticos muy al estilo de los hermanos Coen donde se mezclan la extorsión, la traición, la decepción, el chantaje, el sexo y las drogas.', '/EJFkJD9BH400jfzKz3W5xLYHQa.jpg', '/77ElMccPnTMPouRxSdbJ4nEjf69.jpg', 7.9, 'GiwMMziJdqg', array['1001']::text[], 881, null, 'segura', null),
(857, 'movie', 'Salvar al soldado Ryan', 'Salvar al soldado Ryan', 'Saving Private Ryan', 1998, 'Steven Spielberg', 'Segunda Guerra Mundial, 1944. Tras el desembarco de los Aliados en Normandía, a un grupo de soldados americanos se le encomienda una peligrosa misión: poner a salvo al soldado James Ryan. Los hombres de la patrulla del capitán John Miller deben arriesgar sus vidas para encontrar a este soldado, cuyos tres hermanos han muerto en la guerra. Lo único que se sabe del soldado Ryan es que se lanzó con su escuadrón de paracaidistas detrás de las líneas enemigas.', '/dcKfD8xWf8XnS3tHVp7v331wdNT.jpg', '/bdD39MpSVhKjxarTxLSfX6baoMP.jpg', 8.2, 'RYExstiQlLc', array['1001']::text[], 882, null, 'segura', null),
(9464, 'movie', 'Buffalo 66', 'Buffalo ''66', 'Buffalo ''66', 1998, 'Vincent Gallo', 'Es invierno en Buffalo, Nueva York. Billy Brown acaba de salir de la cárcel después de cinco años tras una apuesta poco acertada que no pudo pagar. Sin embargo, ha engañado a sus padres diciéndoles que trabaja para el Gobierno en un importante proyecto y que está casado con una preciosa joven. Desesperado por impresionar a sus padres, y sin esposa o novia de ninguna clase, Billy rapta impulsivamente a Layla y la obliga a representar el papel ante sus extravagantes progenitores.', '/u7mSqUsQyYpEWpovr55XDcT7v3d.jpg', '/oCcRRoalUWy83x3gqhCIl6pPUAi.jpg', 7.1, 'r7JXNyiPBIQ', array['1001']::text[], 884, null, 'segura', null),
(11545, 'movie', 'Rushmore', 'Academia Rushmore', 'Rushmore', 1998, 'Wes Anderson', 'Max Fisher (Jason Schwartzman), un estudiante de Rushmore, una de las escuelas más prestigiosas del país, es el editor del periódico escolar y el capitán y presidente de numerosos clubs y sociedades; pero también es un pésimo estudiante; por eso, no deja de pensar que algún día lo expulsarán del colegio. Max se enamora de la elegante profesora Miss Cross (Olivia Williams), pero su cortejo fracasa cuando se entera de que el señor Blume (Bill Murray), el padre de dos compañeros de clase, también intenta conquistar el amor de la profesora.', '/hSJ6swahAuZ8wM96lHDTwQPXUvZ.jpg', '/m6AI69LyhJu4o7auQNTmjyMHBVT.jpg', 7.4, '846UzdeHI1g', array['1001']::text[], 884, null, 'segura', null),
(104, 'movie', 'Corre, Lola, corre', 'Corre Lola, corre', 'Lola rennt', 1998, 'Tom Tykwer', 'Manni es un ladrón de poca monta que acepta participar en un gran golpe: vender unos diamantes robados por cien mil marcos que debe entregar a mediodía a un traficante. Pero pierde la bolsa que contiene el dinero en el metro de Berlín. Como último recurso, llama a su novia, Lola (de veinte años, cabellos rojos, frágil pero decidida), y le explica la situación. Son las once y cuarenta minutos; si en veinte minutos Manni no ha recuperado el dinero, es hombre muerto. Desesperada, la joven se precipita hacia la capital. Tiene veinte minutos para encontrar cien mil marcos, reunirse con Manni y salvar al hombre de su vida.', '/ke7jgNx9bgQZrjNOdkJEjWxIvpw.jpg', '/wRcm3iwi4BeMN59U4fjO7u3dOVI.jpg', 7.3, 'ZCYnsUdO6H0', array['1001']::text[], 885, null, 'segura', null),
(452, 'movie', 'Los idiotas', 'Los idiotas', 'Idioterne', 1998, 'Lars von Trier', 'Un grupo de amigos se reune con la intención de liberarse de las ataduras morales que la sociedad imprime sobre los individuos. Para ello, se hacen pasar por retardados mentales. El grupo se dedica a enfrentar a la sociedad con sus idioteces.', '/rTS5bnfnzt6t9iOADIsWHLEnjZR.jpg', '/7yJvYCJzPWuqBDR0Eplh3NbnR9h.jpg', 6.5, 'QbF80Gu80-4', array['1001']::text[], 886, null, 'segura', null),
(473, 'movie', 'Pi', 'Pi, fe en el caos', 'Pi', 1998, 'Darren Aronofsky', 'Max es un brillante matemático que está a punto de dar con el descubrimiento más importante de su vida: la decodificación del sistema numérico que rige el aparente caos del mercado bursátil. Pero primero ha de encontrar el valor del número PI. Mientras se acerca a la verdad, y afectado periódicamente por unas brutales jaquecas, Max es acosado por una agresiva firma de Wall Street y una secta judía que pretende descifrar los secretos ocultos tras los textos sagrados. Todos ansían apropiarse del inminente hallazgo de Max', '/iauKJI5oeCAUeMfvmhCHuYd5vN4.jpg', '/pVmCanXNPYqE74cJoL0U6C9ONf5.jpg', 7.1, 'yRjkQT9xLZs', array['1001']::text[], 886, null, 'segura', null),
(10683, 'movie', 'Happiness', 'Happiness', 'Happiness', 1998, 'Todd Solondz', 'Happiness es un agudo retrato de varias personas conectadas por lazos familiares o sociales, viviendo en estado de desesperación o de simple depresión, y forzadas a tomar actitudes delictivas o inmorales. Verdadera, trágica y divertida, es una película de culto en el cine americano de los años 90.', '/rYfUcEV88Z3gENrfYTE6i8yBkDr.jpg', '/3AE92av4pGYx9NKKss7x5zEgEOS.jpg', 7.4, '1eOzYczx-Xk', array['1001']::text[], 887, null, 'segura', null),
(8741, 'movie', 'La delgada línea roja', 'La delgada línea roja', 'The Thin Red Line', 1998, 'Terrence Malick', 'Segunda Guerra Mundial, isla de Guadalcanal, 1942. Un grupo de hombres pertenecientes a la compañía de fusileros del ejército ''C de Charlie'' combate contra el ejército japonés por la conquista de una estratégica colina. Allí, los hombres sufren grandes cambios, padecen y, en última instancia, descubren aspectos fundamentales de sí mismos. Los soldados forman parte del envío de nuevas unidades del ejército para proceder al relevo de las unidades de infantería de marina agotadas por el combate.', '/234oXaXKIcyXpWMMFISsZ94tas9.jpg', '/hsDyfAk2ml82IrpPC4AHvxvuTsn.jpg', 7.4, 'ejm0XvT3rB8', array['1001']::text[], 888, null, 'segura', null),
(544, 'movie', 'Algo pasa con Mary', 'Algo pasa con Mary', 'There''s Something About Mary', 1998, 'Bobby Farrelly, Peter Farrelly', 'Ted Strohehmann ha vivido angustiado durante 14 años de su vida, la razón de su desgracia no es otra que la famosa Mary Jensen, la chica que todos desean y con la que por fin, consigue tener una cita en la fiesta de fin de curso.', '/dSOfZ9Ni0Nd7dAXR2CT2JI4ljsl.jpg', '/egJQ3nIon5fT8wyXcKRHzvmtZpD.jpg', 6.6, '3CHwXQjDM4Q', array['1001']::text[], 890, null, 'segura', null),
(56653, 'movie', 'Sombre', 'Sombre', 'Sombre', 1998, 'Philippe Grandrieux', 'A serial killer stalks a woman he befriended after her car broke down.', '/qHf1bZEpo5UE6J8qxMnfTkk3zqh.jpg', '/4STEylBCabNW3Zx689YrqAj6Hwa.jpg', 6.3, 'ncqQPs_FasI', array['1001']::text[], 890, null, 'segura', null),
(565, 'movie', 'Ring', 'The Ring (La señal)', 'The Ring', 2002, 'Gore Verbinski', 'Rachel Keller es una periodista de investigación que no da mucho crédito a lo que considera una especie de leyenda urbana: al parecer, circula por ahí una cinta de vídeo con imágenes aterradoras, que va acompañada de una llamada telefónica en la que se predice, con una semana de antelación, la muerte de quien las ha visto. Sin embargo, cuando cuatro adolescentes encuentran la muerte exactamente una semana después de ver el vídeo, la curiosidad se apodera de ella y no parará hasta encontrar la cinta y verla.', '/4TPPSB8OAtgYo9EdFzr7tsTsLDB.jpg', '/6tuNQ16hC4Qp7wjTweKzUnnLBkI.jpg', 6.7, 'CG7BAY6_hsw', array['1001']::text[], 891, null, 'segura', null),
(20617, 'movie', 'Gohatto (Tabú)', 'Gohatto', '御法度', 1999, 'Nagisa Ōshima', 'Japón, siglo XIX. En el templo Nishi-Honganji, la milicia Shinsengumi está seleccionando nuevos reclutas para convertirlos en guerreros samurais. El comandante Isami Kondo y el teniente Toshizo Hijikata son los encargados de supervisar el proceso de adiestramiento que exige que cada aspirante se enfrenté a Soji Okita, el mejor hombre de la milicia.', '/vClnhgB3stCE6uvHMRmnGYQneiP.jpg', '/48z4fEXAVwYXUnp8SVuQ94ohsRl.jpg', 6.6, 'LCQvBZ3xptA', array['1001']::text[], 892, null, 'segura', null),
(14626, 'movie', 'Beau travail', 'Buen trabajo', 'Beau Travail', 2000, 'Claire Denis', 'Un sargento de la Legión Extranjera en Djibouti, África, siente atracción, luego celos y, finalmente, odio por uno de sus soldados más sobresalientes. El enfrentamiento entre los dos hombres se convierte en la única guerra concreta para ellos, sumergidos en el tedio del entrenamiento y los rituales cotidianos de los militares en tiempos de paz. Libre adaptación de la novela "Billy Budd", de Herman Melville.', '/7aVQFvGkLnpA71mYoDkVkzSzBZM.jpg', '/1C84Yg3F2CgGJlOilvXBP8OZCMB.jpg', 7.1, 'Hh4HzACZOOQ', array['1001']::text[], 893, null, 'segura', null),
(2667, 'movie', 'El proyecto de la bruja de Blair', 'El proyecto de la bruja de Blair', 'The Blair Witch Project', 1999, 'Daniel Myrick, Eduardo Sánchez', 'Durante el octubre de 1994, tres estudiantes de cine en el Montgomery College, Heather Donahue, Joshua Leonard y Michael Williams realizaron la propuesta de crear un proyecto para presentarla en la clase de cine, el proyecto llamado por Heather "El Proyecto de la Bruja de Blair" contaba de entrevistas con los residentes del pueblo de Burkittsville, Maryland, sobre la bruja local.', '/4VkdY6GlFchXcHgg3Bsl1A73jsH.jpg', '/ghPJw3XfhELokIf6V5QL0VpsXtK.jpg', 6.4, 'AcTh2YItSaM', array['1001']::text[], 894, null, 'segura', null),
(11489, 'movie', 'Rosetta', 'Rosetta', 'Rosetta', 1999, 'Luc Dardenne, Jean-Pierre Dardenne', 'Rosetta, una joven de 17 años que vive con su madre en una caravana, busca desesperadamente un trabajo digno.', '/uWupE6GXDPX608B5cuK5s4sckYt.jpg', '/1ZBPashbl6CQ3IhfbM38A67tNnj.jpg', 7.1, 'woN2P4r65oA', array['1001']::text[], 895, null, 'segura', null),
(6415, 'movie', 'Tres reyes', 'Tres reyes', 'Three Kings', 1999, 'David O. Russell', 'En marzo de 1991, el capitán Archie Gates, los sargentos Troy Barlow y Chief Elgin, y el soldado Conrad Vig matan el tiempo en el desierto iraquí mientras aguardan el fin de la guerra y la vuelta a la aburrida y desesperanzada vida civil que les espera en casa. Cuando descubren un mapa que indica la ubicación de una reserva de oro Kuwatí robado por los iraquíes, los cuatro hombres deciden iniciar su propia guerra para llegar hasta el oro. Por el camino irán descubriendo las verdaderas condiciones de vida del pueblo iraquí, convirtiendo su misión en una historia de redención que cambiará todos sus puntos de vista y pondrá a prueba su humanidad.', '/bGEsaXcVgn9AzW93xPybJcpDjEU.jpg', '/gysZn2XnFlDDQROXdBPiku4Aujg.jpg', 6.7, 'Bdal5c1TfmE', array['1001']::text[], 895, null, 'segura', null),
(99, 'movie', 'Todo sobre mi madre', 'Todo sobre mi madre', 'Todo sobre mi madre', 1999, 'Pedro Almodóvar', 'Madrid. Manuela, una madre soltera, ve cómo su hijo muere el día en que cumple 17 años, por correr para conseguir el autógrafo de su actriz favorita. Decide entonces viajar a Barcelona en busca del padre de su hijo, un travestido llamado Lola, que ignoraba que tenía un hijo. Encuentra también a su amigo Agrado, otro travesti, y a través de él conoce a Rosa, una monja española y, por pura casualidad, Manuela termina convirtiéndose en la asistente de Huma Rojo, la actriz que admiraba su hijo.', '/evvT3HUwoQYoPQXWFO10R6AvhxG.jpg', '/tilClWjFZeUTGJu0pxgF72fvUmN.jpg', 7.6, 'hcVEvcP1iAc', array['1001']::text[], 896, null, 'segura', null),
(334, 'movie', 'Magnolia', 'Magnolia', 'Magnolia', 1999, 'Paul Thomas Anderson', 'La película consta de nueve tramas paralelas que tienen lugar en el Valle de San Fernando, en Los Angeles: un niño prodigio, el presentador de un concurso de televisión, un ex-niño prodigio, un moribundo, su hijo perdido, la mujer y el enfermero del moribundo. Son historias aparentemente independientes, pero que guardan entre sí una extraña relación. Magnolia es el retrato de la vida americana visto a través de una serie de viñetas cómicas y conmovedoras.', '/wzy5ssxNL5OlPjITaY1OeOeeFyR.jpg', '/mFfyE5DPFDqoes4HIcElHc2a15y.jpg', 7.7, 'cxcegktcxSM', array['1001']::text[], 896, null, 'segura', null),
(550, 'movie', 'El club de la lucha', 'El club de la lucha', 'Fight Club', 1999, 'David Fincher', 'Un hombre consumido por el insomnio y una vida sin sentido conoce a Tyler Durden, un carismático anarquista que lo arrastra a un club secreto donde el dolor despierta algo dormido. Lo que comienza como liberación pronto se convierte en una guerra contra el sistema…', '/sgTAWJFaB2kBvdQxRGabYFiQqEK.jpg', '/c6OLXfKAk5BKeR6broC8pYiCquX.jpg', 8.4, 'aIo4Adm96EA', array['1001']::text[], 898, null, 'segura', null),
(47439, 'movie', 'Le temps retrouvé', 'El Tiempo Recobrado', 'Le Temps retrouvé', 1999, 'Raúl Ruiz', 'Marcel Proust (1871-1922) está en su lecho de muerte. Ver fotografías trae recuerdos de su infancia, su juventud, sus amantes y la forma en que la Gran Guerra puso fin a un estrato social. Sus recuerdos no están en un orden particular, se mueven hacia adelante y hacia atrás en el tiempo. Marcel en varias edades interactúa con Odette, con la bella Gilberte y su marido condenado, con el barón de Charlus que busca el placer, con la amante de Marcel Albertine y con otros; presentes también en la memoria están la querida madre y abuela de Marcel. Parece como si vivir es recordar y capturar recuerdos es crear una obra de gran arte. Los recuerdos son paralelos al volumen final de la novela de Proust.', '/uJJjBbIg1wnOm6QRiKgK1SaRVew.jpg', '/7rOFCemUdldeNMdf3qURElant2K.jpg', 6.3, 'b7SDy6Jxm2s', array['1001']::text[], 898, null, 'segura', null),
(492, 'movie', 'Cómo ser John Malkovich', 'Cómo ser John Malkovich', 'Being John Malkovich', 1999, 'Spike Jonze', 'La vida de Craig Schwartz está llegando al final de un ciclo. Craig es un marionetista callejero con un gran talento, pero él tiene la impresión de que su vida carece de sentido. Nueva York ha cambiado mucho y la gente no le presta mucha atención. Lleva diez años casado con Lotte, que trabaja en una tienda de animales y está obsesionada con su trabajo. Él consigue encontrar trabajo en la planta 7''5 del edificio Mertin-Flemmer de Manhattan, donde encuentra una pequeña puerta que le permite el acceso a un pasillo secreto que le aspira y que le permite acceder al cerebro de John Malkovich.', '/wkjcsh2phfBeSAgvR1wzzzHaLWu.jpg', '/1Nyjb7aeRKynWgmOl8he5ZcvWLm.jpg', 7.4, 'sfVor5JLBM4', array['1001']::text[], 899, null, 'segura', null),
(14, 'movie', 'American Beauty', 'American Beauty', 'American Beauty', 1999, 'Sam Mendes', 'Divertida, inquietante y sorprendente incursión en la América suburbana a través de las vidas de Lester y Carolyn, una pareja perteneciente a la clase medio-alta cuyo matrimonio -y cuyas vidas- lentamente se deshacen. Carolyn odia a su marido, su hija lo desprecia y su jefe está a punto de despedirlo. Así que Lester decide cambiar algunas cosas en su vida; a medida que va siendo más libre, consigue ser más feliz, lo que enfurece más a su esposa y a su hija.', '/wdXHzwh4DCifigYD50YEYM6CJS3.jpg', '/2ndw55F40IkALzWyjCCza3M6nqM.jpg', 8.0, 'CQH51MGFwpY', array['1001']::text[], 900, null, 'segura', null),
(43423, 'movie', 'El viento nos llevará', 'El viento nos llevará', 'باد ما را خواهد برد', 1999, 'Abbas Kiarostami', 'El rodaje de una película en la pequeña localidad kurdo-iraní de Siah Dareh provocará una pequeña revolución entre los habitantes del pueblo, convencidos de que los miembros del rodaje son en realidad buscadores de un tesoro que se halla en el cementerio local.', '/6LqsRiXnuUsF4dtLPp7UsZDe5M8.jpg', '/b9UPNXGV7mEUmLejR8caJIJijow.jpg', 7.1, 'xq1gXC3119A', array['1001']::text[], 900, null, 'segura', null),
(603, 'movie', 'Matrix', 'Matrix', 'The Matrix', 1999, 'Lana Wachowski, Lilly Wachowski', 'Thomas Anderson lleva una doble vida: por el día es programador en una importante empresa de software, y por la noche un hacker informático llamado Neo. Su vida no volverá a ser igual cuando unos misteriosos personajes le inviten a descubrir la respuesta a la pregunta que no le deja dormir: ¿qué es Matrix?', '/tpW2X2DvxtTHJ61iJ7zNYYrJihs.jpg', '/tlm8UkiQsitc8rSuIAscQDCnP8d.jpg', 8.3, 'Zd8Jw1Z_j4w', array['1001']::text[], 901, null, 'segura', null),
(745, 'movie', 'El sexto sentido', 'El sexto sentido', 'The Sixth Sense', 1999, 'M. Night Shyamalan', 'El Dr. Malcom Crowe es un conocido psicólogo infantil obsesionado con el doloroso recuerdo de un joven paciente desequilibrado al que fue incapaz de ayudar. Cole Sear es un aterrorizado y confuso niño de ocho años que necesita tratamiento, y Crowe ve la oportunidad de redimirse haciendo todo lo posible por ayudarle. Sin embargo, el psicólogo infantil no está preparado para conocer la terrible verdad acerca del don sobrenatural de su paciente: recibe visitas no deseadas de espíritus atormentados.', '/pvjph7FouToPBY3PhTvTyOYoJDX.jpg', '/6TjllWT3cGrPFyqDXurVZ3L8bBi.jpg', 8.0, 'HXG4HTIlc1U', array['1001']::text[], 902, null, 'segura', null),
(44379, 'movie', 'Los espigadores y la espigadora', 'Los Espigadores y la espigadora', 'Les Glaneurs et la Glaneuse', 2000, 'Agnès Varda', 'Recorriendo Francia, Agnès Varda se ha encontrado con espigadores, recolectores, gente que busca entre la basura. Por necesidad, o por puro azar, estas gentes recogen los objetos desechados por otros. Su mundo es sorprendente. Y la directora, a su manera, es también una especie de espigadora que selecciona y recoge imágenes aquí y allá.', '/uHodWWNq6CU3cnss2QyHT7c8WPf.jpg', '/yvafnYvrxnwD3MrXcc18sUrkHqU.jpg', 7.7, 'XZF3VRGgxTU', array['1001']::text[], 903, null, 'segura', null),
(47244, 'movie', 'La cautiva', 'La cautiva', 'La Captive', 2000, 'Chantal Akerman', 'Simon (Stanislas Merhar) retiene a Ariane (Sylvie Testud) en su piso parisino e intenta saberlo todo sobre ella; no la deja salir sola y la somete a un incesante interrogatorio para poder controlar sus deseos y movimientos. A pesar de todo, Ariane consigue conservar, gracias a un cúmulo de mentiras, un espacio de libertad, tanto físico como mental. Se inspira en la obra de Marcel Proust "La Prisonnière", quinto tomo de su gran obra "A la recherche du temps perdu" ("En busca del tiempo perdido").', '/i5t2LANNUGap7J3yDMpkaBa6K5u.jpg', '/5bAnFKlLcjRd6SK3it3tCvfwc2C.jpg', 5.7, 'A32wjB41wW8', array['1001']::text[], 904, null, 'segura', null),
(18079, 'movie', 'Nueve reinas', 'Nueve reinas', 'Nueve reinas', 2000, 'Fabián Bielinsky', 'Dos estafadores se cruzan con la oportunidad de vender una plancha de estampillas falsas. Con Ricardo Darín y Gastón Pauls.', '/v8l85vxFe9J1uEvK9qyIMBlYJNv.jpg', '/e4tZvefBtA6P1T0vAPfeXG4Bj3r.jpg', 7.8, 'O2D3rXfNjWw', array['1001','cine_argentino']::text[], 904, null, 'segura', null),
(843, 'movie', 'Deseando amar', 'Deseando amar', '花樣年華', 2000, 'Wong Kar-wai', 'Hong Kong, 1962. Chow, redactor jefe de un diario local, se muda con su mujer a un edificio habitado principalmente por gentes de Shanghai. Allí conoce a Li-zhen, una joven que acaba de instalarse en el mismo edificio con su esposo. Ella es secretaria de una empresa de exportación y su marido está continuamente de viaje de negocios. Como la mujer de Chow también está casi siempre fuera de casa, Li-zhen y Chow pasan cada vez más tiempo juntos y se hacen muy amigos. Un día, ambos descubrirán que sus respectivos cónyuges los están traicionando.', '/r1kobz0ceeNdxzCntkSL5Rzkevi.jpg', '/ffQFnAUm2Uu4RU0nijpjPRf9TBT.jpg', 8.1, 'f3dBlMEsF9I', array['1001']::text[], 905, null, 'segura', null),
(49167, 'movie', 'Ali Zaoua, príncipe de Casablanca', 'Ali Zaoua, príncipe de Casablanca', 'Ali Zaoua, prince de la rue', 2001, 'Nabil Ayouch', 'Ali, Kwita, Omar y Boubker son niños de la calle de Casablanca. Desde que abandonaron a Dib y su pandilla han estado viviendo en el puerto, pero Ali quiere ir más alla: quiere convertirse en marinero y viajar por el mundo. Un día, durante una confrontación con la pandilla de Dib, Ali es asesinado. Una vez devuelto el cuerpo al puerto podrían haberse olvidado de él y abandonarlo, pero deciden enterrarlo como un príncipe. Los tres chicos se embarcan en una serie de encuentros que les permiten reconstruir el sueño de su amigo, encontrar la isla de los dos soles de la que tanto hablaba Ali. Gradualmente este sueño se convierte en su objetivo, en su razón de vivir.', '/5y7UwZnOKXQ7iHKnaoI05POhyDk.jpg', '/9JLub8iSdrUiNOIoJbCx7ZJlHp6.jpg', 6.7, 'o-fMO7c-Ly4', array['1001']::text[], 906, null, 'segura', null),
(98, 'movie', 'Gladiator', 'Gladiator', 'Gladiator', 2000, 'Ridley Scott', 'En el año 180, el Imperio Romano domina todo el mundo conocido. Tras una gran victoria sobre los bárbaros del norte, el anciano emperador Marco Aurelio decide transferir el poder a Máximo, bravo general de sus ejércitos y hombre de inquebrantable lealtad al imperio. Pero su hijo Cómodo, que aspiraba al trono, no lo acepta y trata de asesinar a Máximo.', '/90QFOG5zSN4cbrIVs4DL4ePAuA5.jpg', '/Ar7QuJ7sJEiC0oP3I8fKBKIQD9u.jpg', 8.2, 'W3xjHIdaGww', array['1001']::text[], 907, null, 'segura', null),
(49709, 'movie', 'Kippur', 'Kippur', 'כיפור', 2000, 'Amos Gitai', '6 de octubre de 1973, todo está en calma en Israel, es la fiesta de Yom Kippour (Día del Perdón)... cuando súbitamente estalla la guerra. Weinraub y su amigo Russo parten hacia el sur del Golán en busca de Egoz, la unidad especial donde hicieron el servicio militar. Terminan llegando a la base aérea de Ramat donde formarán parte de un equipo de rescate a bordo de un helicóptero.', '/2zGYk8YIAkPohmS9Hg39c7u1qU3.jpg', '/b7BCGWuXsc68kU7jEkjfhgajm2O.jpg', 5.3, null, array['1001']::text[], 908, null, 'segura', null),
(25538, 'movie', 'Yi yi', 'Yi Yi', '一一', 2000, '楊德昌', 'NJ Jian, su esposa Min-Min y sus dos hijos forman una típica familia de clase media, que comparte su apartamento en Taipei con la anciana madre de Min-Min. NJ tiene 45 años y trabaja como socio en una empresa informática que el año anterior obtuvo importantes beneficios, pero que pronto podría quebrar si no cambia de estrategia. Las cosas empiezan a ir mal para los Jian cuando el hermano de Min-Min, Ah-Di, se casa. De alguna manera entre todos los problemas que tienen deben aprender lo hermosa que es la vida y cómo hay que cuidarla, sea cual sea la situación que nos toque vivir.', '/mlgapXNnBuApMzBc2jVKZQvuFMY.jpg', '/x903dx8Km6XNLFEmvbXc98vePSV.jpg', 8.0, 'PxgrzNFwyqY', array['1001']::text[], 908, null, 'segura', null),
(641, 'movie', 'Réquiem por un sueño', 'Réquiem por un sueño', 'Requiem for a Dream', 2000, 'Darren Aronofsky', 'Harry (Jared Leto) vive con su atormentada madre Sara (Ellen Burstyn), y mientras él sueña con una vida mejor, ella está permanentemente a dieta para el día que pueda cumplir su mayor ilusión; aparecer en su concurso televisivo preferido. La ambición de Harry y su novia Marion (Jennifer Connelly) es hacerse ricos vendiendo droga con su amigo Tyrone (Marlon Wayans), y utilizar las ganancias para abrir un negocio propio, pero nunca llega el dinero suficiente para iniciar su plan. A pesas de todo, Harry y Marion no se resignan a vivir una existencia que consideran despreciable, por lo que harán lo impensable para conseguir la vida que anhelan.', '/2B5brHMhaHN1d9KmdeZI6RlU3aE.jpg', '/fAGYRJCujRBMw7TCuTp893eSG8e.jpg', 8.0, 'NEKjZSTo0Uk', array['1001']::text[], 909, null, 'segura', null),
(55, 'movie', 'Amores perros', 'Amores perros', 'Amores perros', 2000, 'Alejandro González Iñárritu', 'Ciudad de México: un fatal accidente automovilístico afecta trágicamente a tres personas. Octavio, un joven adolescente, decide fugarse con Susana, la esposa de su hermano; el Cofí, su perro, se convierte en el medio para conseguir el dinero que necesitan para poder escapar juntos. Al mismo tiempo, Daniel, un hombre de 42 años, deja a su esposa y a sus hijos para irse a vivir con Valeria, una hermosa modelo. El mismo día en que ambos festejan su nueva vida, el destino hace que Valeria sea víctima del trágico accidente.', '/bVK4CPluBY9LFkzCAwhG5Fs04HE.jpg', '/iTkxwBriD9YKg4Q35qWEIlLXd6e.jpg', 7.6, '_P29GF_NbDc', array['1001']::text[], 910, null, 'segura', null),
(1597, 'movie', 'Los padres de ella', 'Los padres de ella', 'Meet the Parents', 2000, 'Jay Roach', 'Greg Focker es un enfermero algo patoso que, tras anunciar su compromiso con novia Pam, tiene que pasar unos días con los padres de ella, para conocerles. Su encuentro inicial no será muy afortunado, en especial por las suspicacias que Greg levanta en el estricto padre de la novia, un padre protector exagente de la CIA al que es muy difícil impresionar. Desde el principio, Jim rechaza por completo a Greg, pero a medida que lo conoce mejor, su rechazo se convierte en absoluto desprecio, y se encarga de convertirse en la peor pesadilla de este hombre que, a pesar de amar a su novia y querer dar una buena primera impresión, cada vez se hunde más en el lodo de su propia ineptitud, y deberá luchar mucho para poder cambiar la pésima opinión que tienen de él los parientes de su novia.', '/bRMTF8DS5UlWTQk7eEHR3W44Ga1.jpg', '/qcVrlyPFlPgCsmzorvELvpJN9Be.jpg', 6.7, 'I18TOdCvvdM', array['1001']::text[], 911, null, 'segura', null),
(47588, 'movie', 'Signs & Wonders', 'Signs & Wonders', 'Signs & Wonders', 2001, 'Jonathan Nossiter', 'Under the influence of signs and premonitions, a man allows himself to veer in and out of a love affair with his colleague.', '/zCFVwUqlsRikNNSKgXM1Yq2eQEo.jpg', '/lqkfkcG351Ucrd6ZDCmxqlezMrx.jpg', 3.9, 'PLHMlLNoEYc', array['1001']::text[], 911, null, 'segura', null),
(146, 'movie', 'Tigre y dragón', 'Tigre y dragón', '卧虎藏龍', 2000, 'Ang Lee', 'China del año 43 (1779) y ambientada en la historia de la Dinastía Quing. Li Mu Bai, un virtuoso de las artes marciales, tiene en su poder una espada mágica conocida como "Destino Verde". Éste no quiere seguir siendo un guerrero, por lo que decide darle la espada a su mejor amigo, Sir Te. Antes de que llegue el momento de entregarla, se la confía a su enamorada, la guerrera Yu Shu Lien, quien será la encargada de llevarla a la ciudad de Pekín, donde se encuentra su compañero. Sin embargo, una noche, un enmascarado entra en la casa de Sir Te y roba la espada. Así, Mu Bai y Shu Lien se lanzarán en la búsqueda de "Destino Verde", despertando, con ello, viejos fantasmas del pasado.', '/cNHT7JrAzPMMSVmI9XBZpYkeocr.jpg', '/nSm9cij9VRrGDoZoS16CPnX0FqK.jpg', 7.4, 'q-HrIQLdaNE', array['1001']::text[], 912, null, 'segura', null),
(1900, 'movie', 'Traffic', 'Traffic', 'Traffic', 2000, 'Steven Soderbergh', 'El juez Robert Wakefield es nombrado por el Presidente de los Estados Unidos para supervisar los grupos de lucha contra la droga y su coordinación con las autoridades de México. Sin embargo su entusiasmo inicial por la posición de prestigio alcanzada se acabará cuando se dé cuenta de que su hija adolescente Caroline, de 16 años, se ha convertido en una drogadicta -hecho que le ocultaba su esposa Barbara-. Mientras tanto, al sur de la frontera, el agente mexicano Javier Rodriguez intenta librar su propia batalla contra la droga.', '/wcVdkwQbygfSIqOi2ec8jlq7x08.jpg', '/nkMgY1XFLWr91najzfvwie8LyYF.jpg', 7.1, 'sZnOWu68Vw4', array['1001']::text[], 914, null, 'segura', null),
(16, 'movie', 'Bailar en la oscuridad', 'Bailar en la oscuridad', 'Dancer in the Dark', 2000, 'Lars von Trier', 'La película se desarrolla en Estados Unidos en el año 1964. Selma (Björk) es una inmigrante checa que se muda a aquel país con su hijo Gene. Además padece una enfermedad hereditaria degenerativa que le está ocasionando una rápida ceguera progresiva. Por este motivo Selma ahorra centavo a centavo en una lata que guarda en su cocina para pagar una operación que evite que su hijo sufra el mismo destino.', '/DibSnXZBioqf8NngFlrAlmzVs.jpg', '/vxvzf0cGtFY2Vpw5ULWumCIW6Ri.jpg', 7.8, 'RhSjevRpWLo', array['1001']::text[], 915, null, 'segura', null),
(77, 'movie', 'Memento', 'Memento', 'Memento', 2000, 'Christopher Nolan', 'Leonard Shelby sigue la pista del hombre que violó y asesinó a su mujer. Sin embargo, la dificultad de localizar al asesino de su esposa se ve agravada por el hecho de que padece una forma rara e intratable de pérdida de memoria a corto plazo. Aunque puede recordar detalles de la vida antes de su accidente, Leonard no puede recordar qué ha pasado hace quince minutos, adónde va o por qué.', '/fKTPH2WvH8nHTXeBYBVhawtRqtR.jpg', '/7Wev9JMo6R5XAfz2KDvXb7oPMmy.jpg', 8.2, 'mV9l1enMqvk', array['1001']::text[], 916, null, 'segura', null),
(28171, 'movie', 'Kandahar', 'Kandahar', 'Safar e Ghandehar', 2001, 'محسن مخملباف', 'After an Afghanistan-born woman who lives in Canada receives a letter from her suicidal sister, she takes a perilous journey through Afghanistan to try to find her.', '/7WUXpNafn5RuoXBXRQoqzKh3mhY.jpg', '/2LdpiR2Se0xhxSLA9r2al4YSYYj.jpg', 6.2, 'jLe7_SCD3jE', array['1001']::text[], 917, null, 'segura', null),
(1391, 'movie', 'Y tu mamá también', 'Y tu mamá también', 'Y tu mamá también', 2001, 'Alfonso Cuarón', 'Las vidas de Julio y Tenoch, dos jóvenes mexicanos de 17 años, están regidas por su apetito sexual, su amistad, y por su deseo de alcanzar la madurez. Durante una festiva tarde de boda con sus familias, conocen a Luisa, una española de 28 años.', '/a87k2dfqhJi7QbOWOiQWTThyDYK.jpg', '/orIxqUMEcU3DT7qCs16Si8KWjBO.jpg', 7.4, 'inc0vS58ZKg', array['1001']::text[], 918, null, 'segura', null),
(24166, 'movie', '¿Qué hora es allí? (Ni neibian jidian)', '¿Qué hora es?', '你那邊幾點', 2001, '蔡明亮', 'Un vendedor de relojes deambula por las calles de Taipei. Su padre acaba de morir, su madre está enferma y él se encuentra inmerso en una aburrida y deprimente vida. Fortuitamente, un día se topa con una muchacha que se dirige a Paris y quiere comprarle un reloj que le de la hora de las dos ciudades. Inmediatamente se establece una fuerte conexión entre ellos.', '/d7J4T8R62KrxroYLWjrKJQ4FxhN.jpg', '/jtttw606rzded55mXL8F3QYeZwo.jpg', 7.0, 'zoQCaJf5W-c', array['1001']::text[], 918, null, 'probable', '[{"tmdb_id": 24166, "titulo": "¿Qué hora es?", "original": "你那邊幾點", "anio": 2001, "votos": 125, "poster_path": "/d7J4T8R62KrxroYLWjrKJQ4FxhN.jpg", "sim": 0.815}]'::jsonb),
(194, 'movie', 'Amélie', 'Amelie', 'Le Fabuleux Destin d''Amélie Poulain', 2001, 'Jean-Pierre Jeunet', 'Amélie Poulain (Audrey Tautou) es una joven camarera que vive en París y que tiene una imaginación desbordante. Un día, encuentra una caja con objetos antiguos que pertenecían al antiguo inquilino de su apartamento. Amélie decide devolver la caja a su dueño y ver su reacción. Al ver la felicidad que le provoca, Amélie se propone hacer felices a los demás con pequeños gestos. Así, ayuda a sus vecinos, a sus compañeros de trabajo y a su padre, mientras se divierte con sus ocurrencias. Pero en su búsqueda de la felicidad ajena, Amélie se olvida de la suya propia, hasta que conoce a Nino Quincampoix (Mathieu Kassovitz), un joven coleccionista de fotos que le roba el corazón.', '/mYvUib00miJWxWkiXhy3QnrCj96.jpg', '/6n53UI4mX9QMfe2S0Pgt8mGebY1.jpg', 7.9, 'UQRxJfMqQcE', array['1001']::text[], 919, null, 'segura', null),
(129, 'movie', 'El viaje de Chihiro', 'El viaje de Chihiro', '千と千尋の神隠し', 2001, 'Hayao Miyazaki', 'Durante el traslado de su familia a los suburbios, una niña de 10 años de edad deambula por un mundo gobernado por dioses, brujas y espíritus, y donde los humanos se convierten en bestias.', '/2RcxjDykOssx4SfqshewyI9vfSl.jpg', '/m4TUa2ciEWSlk37rOsjiSIvZDXE.jpg', 8.5, '5Fgq4Osh6XQ', array['1001']::text[], 920, null, 'segura', null),
(11447, 'movie', 'La habitación del hijo', 'La habitación del hijo', 'La stanza del figlio', 2001, 'Nanni Moretti', 'En una pequeña ciudad del Norte de Italia, vive apaciblemente una familia formada por los padres (Giovanni y Paola) y dos hijos adolescentes: Irene, la mayor, y Andrea, el pequeño. Giovanni es psicoanalista. En su consulta, situada al lado de su apartamento, sus pacientes le confían sus neurosis, que contrastan con la calma de su propia existencia. Su vida se rige por una serie de costumbres o aficiones: leer, escuchar música, aislarse y agotarse haciendo largas carreras por la ciudad. Un domingo por la mañana, un paciente llama a Giovanni por una urgencia. No puede salir a correr con su hijo tal y como le había propuesto; Andrea sale a bucear con sus amigos, pero no volverá...', '/hudxnoYfL7lIbVOPkyBaRbrVQsn.jpg', '/fA7ptJVPbph8cZLVc1yaZIsTULk.jpg', 7.1, '9WZQ5641lFs', array['1001']::text[], 922, null, 'segura', null),
(1791, 'movie', 'La pianista', 'La pianista', 'La Pianiste', 2001, 'Michael Haneke', 'Una mujer, profesora de piano en un conservatorio, frecuenta cines porno y tiendas de sexo para escapar de la influencia de su dominante madre. Uno de sus alumnos se propone seducirla.', '/pR7lOkoI5XRan0NDqMpuw5eRkx2.jpg', '/tEhvOU8nJp4v9goYwrJTASJJD3C.jpg', 7.3, 'Z-frdy3mYHo', array['1001']::text[], 922, null, 'segura', null),
(8342, 'movie', 'En tierra de nadie', 'En tierra de nadie', 'No Man''s Land', 2001, 'Danis Tanović', 'Guerra de Bosnia, 1993. Dos soldados de bandos distintos, un bosnio y un serbio, se encuentran atrapados entre las líneas enemigas, en tierra de nadie. Un sargento de los cascos azules de las Naciones Unidas se dispone a ayudarlos, contraviniendo las órdenes de sus superiores. Los medios de comunicación no tardan en convertir el asunto en un show mediático de carácter internacional. Mientras la tensión bélica crece y la prensa espera pacientemente nuevas noticias, los dos soldados intentarán por todos los medios salir con vida de tal situación.', '/gcPyWlcuRPsudHP1zXEV8kLQ9jP.jpg', '/e86j48mkpIzFSNutRGcNiltWCNt.jpg', 7.5, 'Ypsnv50Af_I', array['1001']::text[], 923, null, 'segura', null),
(824, 'movie', 'Moulin Rouge!', 'Moulin Rouge', 'Moulin Rouge!', 2001, 'Baz Luhrmann', 'París, alrededor de 1900. El mundo ha sido conquistado por la revolución de Bohemia. Satine, la estrella más rutilante del Moulin Rouge, encandila a toda la ciudad con sus bailes llenos de sensualidad y su enorme belleza. Atrapada entre el amor de Christian, un joven escritor, y la obsesión del duque, lucha por hacer realidad su sueño de convertirse en actriz. Pero, en un mundo en el que vale todo excepto enamorarse, nada es fácil.', '/hE7ovWkqKzPmgrXZhLRIA20Hx6F.jpg', '/vvcLSgiviCIU0J0UcwLqWdU8Iup.jpg', 7.5, '2PpgPxjzbkA', array['1001']::text[], 924, null, 'segura', null),
(480, 'movie', 'La boda del monzón', 'La boda del monzón', 'Monsoon Wedding', 2001, 'Mira Nair', 'Los preparativos de una elegante boda en Nueva Delhi, que durará cuatro días, reflejan los conflictos entre generaciones partidarias de seguir las tradiciones y otras defensoras de la modernidad. A Lalit Verma y a su mujer Pimmi la boda concertada de su hija les lleva casi al borde de un ataque de nervios y de la quiebra. Otras historias paralelas se desarrollan a medida que van llegando a la ciudad parientes procedentes de todo el mundo. El novio llega de Houston (Texas), donde trabaja como ingeniero, para conocer a la novia. La novia, por su parte, acepta el compromiso a regañadientes, pues está enamorada de un presentador de televisión. Los preparativos de la boda exigen contratar a un organizador profesional y el elegido será P.K. Dubey, que es un inteligente joven de clase media.', '/pt1WHixIA2D85EYv30mDyFr4Om7.jpg', '/bEkGHeIZYtULSgEvyjIbGHnMqgf.jpg', 6.8, 'sjQjw-UyAX0', array['1001']::text[], 926, null, 'segura', null),
(9523, 'movie', 'Lantana', 'Lantana', 'Lantana', 2001, 'Ray Lawrence', 'Cuatro matrimonios se ven atrapados en una diabólica red de amor, engaño, sexo y muerte, a la que no todos sobreviven. El detective Leon Zat se mueve por un oscuro laberinto de relaciones humanas en su investigación para resolver el misterio de la desaparición de una mujer casada con un importante hombre de negocios.', '/i2oVRPPjs8vwwj03nEqj4KSQ6iK.jpg', '/s9ivjpkMFQNRNXbfGBGgFGcthCS.jpg', 6.7, '8ayPrLsBs_w', array['1001']::text[], 926, null, 'segura', null),
(570, 'movie', 'À ma soeur!', 'À ma sœur !', 'À ma sœur !', 2001, 'Catherine Breillat', 'La director francesa, tras la polémica "Romance X" (1999), continúa en el terreno del sexo en este filme que retrata el descubrimiento sexual de la adolescencia, desde la perspectiva de dos hermanas ansiosas de perder su virginidad durante unas vacaciones.', '/fjqafvJW9UxiuiVFE0WtGxwvJit.jpg', '/gk7k11v0G9QiSEpDR5fhr6Ihkwa.jpg', 6.1, 'S7K2ZRuwBgg', array['1001']::text[], 927, null, 'segura', null),
(1018, 'movie', 'Mulholland Drive', 'Mulholland Drive', 'Mulholland Drive', 2001, 'David Lynch', 'Betty, una joven aspirante a actriz, llega a Los Ángeles para convertirse en estrella de cine y se aloja en el apartamento de su tía. Allí conoce a Rita, una mujer que padece amnesia a causa de un accidente en Mulholland Drive. Las dos juntas deciden investigar quién es Rita y cómo llegó hasta allí.', '/kLpwkbimTwTbsYixCO3eAdNCQJ8.jpg', '/g9ClaS5EqU0Hk8WIbMNhld0Bk6f.jpg', 7.8, 'iDSsG6bephI', array['1001']::text[], 928, null, 'segura', null),
(9428, 'movie', 'Los Tenenbaum, una familia de genios', 'Los Tenenbaums. Una familia de genios', 'The Royal Tenenbaums', 2001, 'Wes Anderson', 'Royal Tenenbaum y su mujer Etheline, después de tener tres hijos, Chas, Richie y Margot, se han separado. Chas, que trabaja en el sector inmobiliario, parecía tener un don innato para las finanzas internacionales. Margot fue dramaturga y obtuvo una beca Braverman de 50.000 dólares cuando aún estaba en el instituto. Richie fue campeón junior de tenis y ganó los campeonatos de Estados Unidos tres años consecutivos. Pero todos los brillantes recuerdos de los jóvenes Tenenbaums quedan repentinamente borrados por dos décadas de traiciones, fracasos y decepciones de las que consideran que su padre es el principal responsable.', '/zLJ76qtAQXbYTceBYwTAPu0e12P.jpg', '/cbuX448RKetr5Y5cZkmJEfu3xji.jpg', 7.5, '-DNAI9bhBFU', array['1001']::text[], 929, null, 'segura', null),
(8439, 'movie', 'Ônibus 174', 'Ônibus 174', 'Ônibus 174', 2002, 'José Padilha', 'On 12 June 2000, in Rio de Janeiro, Ônibus 174 was taken by an armed young man, threatening to kill all the passengers. Transmitted live on all national networks, this shocking and tragic event became one of violence''s most shocking portraits, and one of the most terrifying examples of police incompetence and abuse in recent years.', '/3AYrrZ03Rmp3XxAD2xYZEeSDdBc.jpg', '/purLFx9MR327mRclyc4sFYjE1cv.jpg', 7.4, null, array['1001']::text[], 930, null, 'segura', null),
(423, 'movie', 'El pianista', 'El pianista', 'The Pianist', 2002, 'Roman Polanski', 'Varsovia, 1939. El pianista polaco de origen judío Wladyslaw Szpilman (Adrien Brody) interpreta un tema de Chopin en la radio nacional de Polonia mientras la aviación alemana bombardea la capital. El régimen nazi ha invadido el país, y como hace en otros países invadidos, lleva a cabo la misma política con respecto a los judíos. Así Szpilman y toda su familia -sus padres, su hermano y sus dos hermanas- se ven obligados a dejar su casa y todo lo que les pertenece para trasladarse con miles de personas de origen judío al ghetto de Varsovia. Mientras Wladyslaw trabaja como pianista en un restaurante propiedad de un judío que colabora con los nazis, su hermano Henryk (Ed Stoppard) prefiere luchar contra los nazis. Pero tres años más tarde, los habitantes del ghetto son trasladados en trenes hacia campos de concentración.', '/mxfLOWnHnSlbdraKfzRn5mqoqk7.jpg', '/c0fB9xk7D1aVb3Bg2rk2SVJcGn.jpg', 8.4, 'og9hFxxdSOg', array['1001']::text[], 931, null, 'segura', null),
(64, 'movie', 'Hable con ella', 'Hable con ella', 'Hable con ella', 2002, 'Pedro Almodóvar', 'Benigno, un enfermero, y Marco, un escritor maduro, coinciden en un espectáculo de Pina Bausch, en el Cafe Müller. En el escenario, dos mujeres con los ojos cerrados y los brazos extendidos se mueven al compás de "The Fairy Queen" de Henry Purcell. La emoción de Marco es tal que rompe a llorar. A Benigno le gustaría decirle que a él también le emociona el espectáculo, pero no se atreve. Meses más tarde, los dos hombres vuelven a encontrarse en la clínica privada "El Bosque", donde Benigno trabaja. Lydia, la novia de Marco, torera de profesión, ha sufrido una cogida y está en coma. Benigno cuida de otra mujer también en estado de coma: Alicia, una estudiante de ballet. El reencuentro entre Marco y Benigno es el comienzo de una intensa amistad. Dentro de la clínica, la vida de los cuatro personajes fluye en todas las direcciones, pasado, presente y futuro, arrastrando a los cuatro a un destino insospechado.', '/7E0ZukUMnSVHvGwHVBF1iOP86RE.jpg', '/rknvDtxOe1uqLX0EFWLHIQxRXcJ.jpg', 7.6, 'zk_obe_xW0w', array['1001']::text[], 932, null, 'segura', null),
(11659, 'movie', 'La mejor juventud', 'La mejor juventud', 'La meglio gioventù', 2003, 'Marco Tullio Giordana', 'Historia de una familia italiana desde los años 60 hasta nuestros días. Dos hermanos, Nicola (Luigi Lo Cascio) y Matteo (Alessio Boni), comparten las mismas esperanzas, los mismos sueños; disfrutan de los mismos libros y de los mismos amigos hasta que conocen a una chica desequilibrada, Giorgia (Jasmine Trinca), que perturba su destino. Mientras Nicola ejerce como psicólogo, Matteo abandona sus estudios e ingresa en el cuerpo de policía.', '/tHyMkciechhnTHTM1ky5OGWrb7N.jpg', '/leF9AKe937UhQsfWGtXfG7tBRvU.jpg', 8.0, 'eIozQwKTxp0', array['1001']::text[], 933, null, 'segura', null),
(670, 'movie', 'Oldboy', 'Old Boy', '올드보이', 2003, 'Park Chan-wook', 'Sin tener idea de cómo llegó a ser encarcelado, drogado y torturado durante 15 años, un hombre desesperado busca vengarse de sus captores.', '/45kRW1xgTq3QrZltL9mY9e9iYkH.jpg', '/rwf5SUTiEsmfkXAgy15R0UtJUtv.jpg', 8.2, '-W8cPij0HgA', array['1001']::text[], 934, null, 'segura', null),
(122, 'movie', 'El señor de los anillos: El retorno del rey', 'El señor de los anillos: El retorno del rey', 'The Lord of the Rings: The Return of the King', 2003, 'Peter Jackson', 'Las fuerzas de Saruman han sido destruidas, y su fortaleza sitiada. Ha llegado el momento de que se decida el destino de la Tierra Media, y por primera vez en mucho tiempo, parece que hay una pequeña esperanza. La atención del señor oscuro Sauron se centra ahora en Gondor, el último reducto de los hombres, y del cual Aragorn tendrá que reclamar el trono para ocupar su puesto de rey. Pero las fuerzas de Sauron ya se preparan para lanzar el último y definitivo ataque contra el reino de Gondor, la batalla que decidirá el destino de todos. Mientras tanto, Frodo y Sam continuan su camino hacia Mordor, a la espera de que Sauron no repare en que dos pequeños Hobbits se acercan cada día más al final de su camino, el Monte del Destino.', '/mWuFbQrXyLk2kMBKF9TUPtDwuPx.jpg', '/ctiw6FZK4N36LmkjSklWEbuvlq9.jpg', 8.5, 'h-9RYiqyqjk', array['1001']::text[], 936, null, 'segura', null),
(338, 'movie', 'Good Bye, Lenin', 'Good bye, Lenin!', 'Good Bye, Lenin!', 2003, 'Wolfgang Becker', 'Berlín, octubre de 1989. Unos días antes de la caída del Muro, la madre de Alex, una mujer orgullosa de sus ideas comunistas, entra en coma. Cuando despierta ocho meses después, su hijo hará lo posible y lo imposible para que no se entere de que está viviendo en una Alemania reunificada y capitalista. Su objetivo es convertir el apartamento familiar en una isla anclada en el pasado, una especie de museo del socialismo en el que su madre viva cómodamente creyendo que nada ha cambiado.', '/32mQrRhkZofgMmGEHVNsTUHARWr.jpg', '/uBLmfG7MyNXPXI50eMs1ZjxpbnV.jpg', 7.5, 'mIjSaHUKD5I', array['1001']::text[], 937, null, 'segura', null),
(153, 'movie', 'Lost in Translation', 'Lost in Translation', 'Lost in Translation', 2003, 'Sofia Coppola', 'Bob Harris y Charlotte son dos norteamericanos que se encuentran en Tokio. Bob es una estrella de cine de mediana edad que ha venido a rodar un anuncio. Charlotte es una mujer joven que acompaña a todas partes a su marido, un fanático del trabajo. Incapaces de dormir, los caminos de Bob y Charlotte se cruzan por casualidad y no tardará en nacer entre ellos una sorprendente amistad. Se aventuran juntos en la vida nocturna de Tokio, comparten inolvidables experiencias con los habitantes de la ciudad y terminan descubriendo una nueva manera de ver la vida.', '/ybXq8xTs6VMx3hM4RDYMXaDZwcz.jpg', '/6ITVHoipvxAS8luzKtHTbPaHLtT.jpg', 7.4, '1s4YQqnbnM8', array['1001']::text[], 938, null, 'segura', null),
(613, 'movie', 'El hundimiento', 'El hundimiento', 'Der Untergang', 2004, 'Oliver Hirschbiegel', 'Berlín, abril de 1945. En las calles de Berlín se libra una encarnizada batalla. Hitler y sus fieles se han atrincherado en un búnker. Entre ellos se encuentra Traudl Junge, la secretaria personal del Führer. En el exterior, la situación se recrudece. A pesar de que Berlín ya no puede resistir más, Hitler se niega a abandonar la ciudad y, acompañado de Eva Braun, prepara su despedida.', '/wQRPfXAB0ORHECs589voFy71ilm.jpg', '/cT80aGpjWZLn8rd7cLtsbktFMhf.jpg', 7.9, 'Fb0Fb31LECY', array['1001']::text[], 939, null, 'segura', null),
(2841, 'movie', 'Largo domingo de noviazgo', 'Largo domingo de noviazgo', 'Un long dimanche de fiançailles', 2004, 'Jean-Pierre Jeunet', 'Cuando la I Guerra Mundial (1914-1918) se acerca a su fin, para una joven francesa está a punto de comenzar la más cruel de las batallas. Mathilde ha recibido la noticia de que su prometido Manech es uno de los cinco soldados heridos que, tras haber sido sometidos a un consejo de guerra, han sido enviados a la tierra de nadie que hay entre el ejército francés y el alemán, lo cual supone una muerte casi segura. Mathilde, que se niega a aceptar esa situación, emprende un extraordinario viaje para conocer el destino de su prometido. Las noticias que va recibiendo sobre Manech son desalentadoras. Aún así, animada por una fe y una esperanza inquebrantables y también por un gran optimismo, sigue su investigación hasta el final. A medida que se acerca a la verdad sobre los desafortunados soldados y su brutal castigo, se ve más envuelta en los horrores de la guerra y en las marcas indelebles que deja en quienes la han vivido.', '/u6DEnb5ki2g3xKBNxd5Z1yWq52M.jpg', '/vOpm4wQk5qIl8UepoKrpaloqaPC.jpg', 7.3, 'BNx2iuOGVVI', array['1001']::text[], 940, null, 'segura', null),
(1777, 'movie', 'Fahrenheit 9/11', 'Fahrenheit 9/11', 'Fahrenheit 9/11', 2004, 'Michael Moore', 'Michael Moore indaga cómo la administración de Bush utilizó el trágico ataque a las Torres Gemelas para su propio beneficio político. Moore nos muestra la controvertida elección de George W. Bush en el año 2000 para seguir su ascenso de mediocre petrolero texano a presidente de Estados Unidos. Tras más de un año de investigación, Michael Moore descubre las oscuras relaciones de negocio entre el padre del Presidente y la familia de Osama Bin Laden, poniendo de relieve que el poder y la riqueza del enemigo número uno de los estadounidenses ha aumentado gracias a este vínculo.', '/9Fha6OFqFBL9bPRLJPhJFmAwib6.jpg', '/mW7HEM3e6Uf9IcBuvEHS8yaQ48M.jpg', 7.1, 'ubX6CJ4rowo', array['1001']::text[], 941, null, 'segura', null),
(9675, 'movie', 'Entre copas', 'Entre copas', 'Sideways', 2004, 'Alexander Payne', 'Miles, un profesor de instituto divorciado y escritor frustrado, y su amigo Jack, un ex-actor famoso a punto de casarse, se embarcan un buen día en un viaje a través de la ruta vinícola de California. Durante el viaje conocerán a dos mujeres y se preguntarán acerca del rumbo que tienen sus vidas, acerca de la felicidad y de sus relaciones pasadas, presentes y futuras.', '/ae4kP6wQsBEmDUO8pZ1UVk9WCA7.jpg', '/zmuRxro8AxPDjACjXTIIDCUNwDl.jpg', 7.1, 'FccttA8wPqc', array['1001']::text[], 942, null, 'segura', null),
(445, 'movie', 'Caché', 'Caché (Escondido)', 'Caché', 2005, 'Michael Haneke', 'Georges es el típico burgués: presenta un programa literario en televisión y lleva una vida acomodada con su mujer y su hijo adolescente. Pero, empieza a recibir unos paquetes anónimos que contienen cintas de vídeo, grabadas desde la calle, y unos dibujos inquietantes cuyo significado es un misterio. No sabe quién los envía; sin embargo, las secuencias que aparecen en las cintas se hacen cada vez más personales, lo que sugiere que el remitente le conoce desde hace algún tiempo. Georges siente que una amenaza se cierne sobre él y su familia, pero, puesto que no hay evidencias de delito alguno, la policía se niega a ayudarlo.', '/ght5BJOCDFRyp9tbQLGWfVjWdtM.jpg', '/mOYIUiSdoLWynoZIGDZSAAUZ3ss.jpg', 7.0, 'pvT_9TqIEtM', array['1001']::text[], 943, null, 'segura', null),
(1986, 'movie', 'Vete y vive', 'Vete y vive', 'Va, vis et deviens', 2005, 'Radu Mihăileanu', 'En 1984, miles de africanos procedentes de 26 países afectados por el hambre terminan en campamentos en Sudán. En una iniciativa de Israel y los Estados Unidos, se realiza una misión para llevar a miles de Judios de Etiopía a Israel. Una madre cristiana obliga a su hijo de nueve años a declararse un Judio para salvarle de la hambruna y la muerte. El niño llega a la Tierra Santa, dice que es huérfano, y es adoptado por una familia francesa sefardí de Tel Aviv, aunque crece con el temor de que se descubra su doble secreto: ni es Judio ni es huérfano, sólo es negro. Descubrirá el amor, la cultura occidental, el judaísmo, pero también el racismo y la guerra en los territorios ocupados.', '/9epxWjiU1epDK3dg8DKnBhHP1bn.jpg', '/12YKdvErSqcMp33ZeNe7MjSW06A.jpg', 7.4, 'Tr1UhP1HxiY', array['1001']::text[], 944, null, 'segura', null),
(67, 'movie', 'Paradise Now', 'Paradise Now', 'Paradise Now', 2005, 'Hany Abu-Assad', 'Khaled y Said son dos jóvenes palestinos, amigos desde la infancia, a los que reclutan para llevar a cabo un atentado suicida en Tel Aviv. Después de una última noche con sus respectivas familias, de las que no les está permitido despedirse, parten hacia la frontera con explosivos pegados al cuerpo. Sin embargo, nada sale como estaba previsto y una serie de contratiempos les obliga a separarse. Entonces tendrán que replantearse su vida y sus convicciones.', '/vYA42i4XCfYmMBCNi1pYAv8eIyK.jpg', '/rnuraNgw9zOlqdDkl8y6lNE2RJb.jpg', 6.9, '9O5KYevUkPw', array['1001']::text[], 945, null, 'segura', null),
(142, 'movie', 'Brokeback Mountain', 'Brokeback Mountain (En terreno vedado)', 'Brokeback Mountain', 2005, 'Ang Lee', 'Verano de 1963. Dos vaqueros, Ennis Del Mar y Jack Twist, se conocen mientras hacen cola para ser contratados por el ranchero Joe Aguirre. Los dos aspiran a conseguir un trabajo estable, casarse y formar una familia. Cuando Aguirre les envía a cuidar ganado a la majestuosa montaña Brokeback, entre ambos surge un sentimiento de camaradería que deriva hacia una relación íntima. Al concluir el verano, tienen que abandonar Brokeback y seguir caminos diferentes.', '/kRgrTPM6uDiLBgASk8j3RBTE49d.jpg', '/vXzqV2RtJlT9WhNEM4NYWCEC6ZI.jpg', 7.8, 'Jd_yMVG9oM0', array['1001']::text[], 946, null, 'segura', null),
(16646, 'movie', 'Russkij kovcheg (El arca rusa)', 'El arca rusa', 'Русский ковчег', 2002, 'Aleksandr Sokúrov', 'El Marqués de Coustine, un diplomático francés del siglo XVIII con una relación de amor/odio hacia Rusia se encuentra en un viaje en el tiempo en el Palacio de Invierno de San Petersburgo -desde los tiempos de Pedro el Grande hasta nuestros días. Con él, un invisible realizador ruso (en off), que está confuso sobre la posición de Rusia en Europa.', '/b7qPeDecDZ9XUCXRQ6Ybml3SHl3.jpg', '/lLQgQy1nX3qocg83BLTCz1911R4.jpg', 7.2, 'ZV1kphEEXn8', array['1001']::text[], 946, null, 'segura', null),
(868, 'movie', 'Tsotsi', 'Tsotsi', 'Tsotsi', 2005, 'Gavin Hood', 'En uno de los barrios más miserables de Johannesburgo (Sudáfrica), Tsotsi, un chaval de 19 años, ha borrado todos sus recuerdos, incluyendo su nombre real. Tsotsi significa "matón" o "gangster" en el argot callejero del guetto. Huérfano desde muy pequeño y obligado a salir adelante por sus propios medios, Tsotsi ha llevado una vida de privaciones extremas, tanto físicas como psíquicas. Tiene escasa conciencia de los sentimientos de los demás y se ha endurecido borrando cualquier sentido de la compasión. Gobernado por el impulso y el instinto, le mueve el miedo que inspira a otros. Sin nombre, sin pasado, sin ningún plan para el futuro, en un presente lleno de rabia, Tsotsi lidera su propio grupo de marginados sociales... (FILMAFFINITY)', '/jTnd54eUwrjxxS9TLHXFa44G72w.jpg', '/gLxgqHpJcMvB6cMTA4hUBxoOMJ1.jpg', 6.9, 'yCO4FbYyZIk', array['1001']::text[], 948, null, 'segura', null),
(1985, 'movie', 'El jardinero fiel', 'El jardinero fiel', 'The Constant Gardener', 2005, 'Fernando Meirelles', 'Basada en el Best Seller de espionaje de John le Carré, cuenta la historia de Justin Quayle (Fiennes) un diplomático británico destinado en Kenya cuya mujer es asesinada junto a un hombre sospechoso de ser su amante, un activista defensor de los derechos humanos de la región. Quayle decide entonces investigar los asesinatos, y comienza a descubrir mucho más de lo que esperaba...', '/xXvD4tPCbR5NbnbEMWctJ5ItEfZ.jpg', '/ksT0nX66UpCVBdvXiXW1byaZtjo.jpg', 7.0, '9FycLyDTCWQ', array['1001']::text[], 949, null, 'segura', null),
